rentPath)!==-1){older=olderData.feed.entry[1]||null}else{older=entry0}} let newer=null;if(newerData.feed&&newerData.feed.entry){const entries=newerData.feed.entry;for(let i=entries.length-1;i>=0;i--){const link=entries[i].link.find((l)=>l.rel==="alternate").href;if(link.indexOf(currentPath)!==-1){newer=entries[i-1]||null;break}}} let html="<div class='aChp'>";if(older){const altLink=older.link.find((l)=>l.rel==="alternate");const title=older.title.$t||"Previous Post";html+=`<a href='${altLink.href}' class='o'><div class='b'>Previous</div><div class='t'>${title}</div></a>`}else{html+="<div></div>"} if(newer){const altLink=newer.link.find((l)=>l.rel==="alternate");const title=newer.title.$t||"Next Post";html+=`<a href='${altLink.href}' class='n'><div class='b'>Next</div><div class='t'>${title}</div></a>`}else{html+="<div></div>"} html+="</div>";container.innerHTML=html}catch(err){console.error("Pager load error:",err)}};const loadRelatedPosts=async(postCategory)=>{const container=document.getElementById("related-posts-placeholder");if(!container||!postCategory||postCategory.length===0)return;const normalLabels=postCategory.map(c=>c.term).filter(t=>!t.startsWith("#"));if(normalLabels.length===0)return;const label=normalLabels[0];const currentPath=window.location.pathname;const shuffle=(arr)=>{const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};try{const res=await fetch(`${getFeedBase()}/feeds/posts/default/-/${encodeURIComponent(label)}?alt=json&max-results=20`);const data=await res.json();const entries=data.feed?.entry||[];let related=entries.filter(e=>e.link.find(l=>l.rel==="alternate").href.indexOf(currentPath)===-1);related=shuffle(related).slice(0,6);if(related.length<3&&normalLabels.length>1){const label2=normalLabels[1];const res2=await fetch(`${getFeedBase()}/feeds/posts/default/-/${encodeURIComponent(label2)}?alt=json&max-results=20`);const data2=await res2.json();const entries2=data2.feed?.entry||[];const existing=new Set(related.map(e=>e.id.$t));const extra=entries2.filter(e=>e.link.find(l=>l.rel==="alternate").href.indexOf(currentPath)===-1&&!existing.has(e.id.$t));related=[...related,...shuffle(extra)].slice(0,6)}if(related.length>0){container.innerHTML=` <div class='related-posts-section'> <h3 class='related-posts-title'>関連記事</h3> <div class='post-grid related-grid'> ${related.map(createPostCard).join("")} </div> </div> `}}catch(err){console.error("Failed to load related posts",err)}};const insertStructuredData=(post)=>{const title=post.title.$t;const url=post.link.find(l=>l.rel==='alternate').href;const published=post.published.$t;const updated=post.updated.$t;const author=post.author[0].name.$t;const thumbnail=getThumbnail(post);const description=post.summary?stripHtml(post.summary.$t).substring(0,200):'';const schema={"@context":"https://schema.org","@type":"Article","headline":title,"url":url,"datePublished":published,"dateModified":updated,"author":{"@type":"Person","name":author,"url":SNS_CONFIG.profile},"description":description};if(thumbnail){schema.image={"@type":"ImageObject","url":thumbnail}} const script=document.createElement('script');script.type='application/ld+json';script.text=JSON.stringify(schema);document.head.appendChild(script)};(function(){const targetPop=document.getElementById('pop-content');const targetRec=document.getElementById('rec-content');const RECENT_MAX_RESULTS=5;const fixDate=(dateStr)=>{if(!dateStr)return"";const match=dateStr.match(/(\d+)月\s+(\d+),\s+(\d+)/);if(match){const month=("0"+match[1]).slice(-2);const day=("0"+match[2]).slice(-2);const year=match[3];return `${year}/${month}/${day}`} const d=new Date(dateStr);if(!isNaN(d.getTime())){const y=d.getFullYear();const m=("0"+(d.getMonth()+1)).slice(-2);const dy=("0"+d.getDate()).slice(-2);return `${y}/${m}/${dy}`} return dateStr};const createItemHtml=(link,thumb,title,date,label)=>{const optimizedThumb=thumb.replace(/\/s[0-9]+(-[a-z])?\//,"/s200-rw/");return ` <li class='recent-post-item'> <a href='${link}' class='recent-post-link'> <img src='${optimizedThumb}' class='recent-post-thumb' alt='${title}' width='80' height='80' loading='lazy'/> <div class='recent-post-info'> <div class='recent-post-title'>${title}</div> <div class='recent-post-meta'> <span class='meta-item'>${svgClock}${date}</span> ${label ? `<span class='meta-item'>${svgTag}${label}</span>` : ""} </div> </div> </a> </li>`};const syncPopular=()=>{const checkExist=setInterval(()=>{const allPP=document.querySelectorAll('[id^="PopularPosts"]');const origin=Array.from(allPP).find(el=>el.getAttribute('id')!=='PopularPosts1')||document.querySelector('#PopularPosts99');if(origin&&origin.querySelectorAll('li.item').length>0){clearInterval(checkExist);const items=origin.querySelectorAll('li.item');let html='';items.forEach(item=>{const a=item.querySelector('a');if(!a)return;const rawDate=item.getAttribute('data-date')||"";const formattedDate=fixDate(rawDate);html+=createItemHtml(a.href,item.querySelector('img')?.src||'',item.querySelector('.item-title').textContent.trim(),formattedDate,item.getAttribute('data-label')||'')});targetPop.innerHTML=html;origin.style.display='none'}},100);setTimeout(()=>clearInterval(checkExist),5000)};window.drawRecent=(json)=>{if(!targetRec||!json.feed.entry)return;targetRec.innerHTML=json.feed.entry.map(entry=>{const title=entry.title.$t;const link=entry.link.find(l=>l.rel==='alternate')?.href||"#";const date=formatDate(entry.published.$t);const label=entry.category&&entry.category.length>0?entry.category[0].term:"";let thumb=entry.media$thumbnail?entry.media$thumbnail.url:"https://via.placeholder.com/150?text=No+Image";return createItemHtml(link,thumb,title,date,label)}).join("")};const setupTabs=()=>{const btnPop=document.getElementById('tab-pop');const btnRec=document.getElementById('tab-rec');const panePop=document.getElementById('panel-pop');const paneRec=document.getElementById('panel-rec');const lamp=document.querySelector('.tab