='dropdown-item' href='${c.url}'>${c.label}</a>`).join(""):`<a class='dropdown-item' href='${item.url}'>${item.label}の記事一覧</a>`;return ` <div class='has-dropdown mobile-accordion'> <a class='nav-link accordion-trigger' href='${item.url}'> ${item.label} <i class='fa-solid fa-chevron-down' style='font-size:0.7rem;'></i> </a> <div class='dropdown-menu'>${childrenItems}</div> </div>`} return `<a class='nav-link' href='${item.url}'>${item.label}</a>`}).join("");let mobileLabelsSection="";if(BLOG_CONFIG.showLabels&&labelHtml){mobileLabelsSection=` <div style='margin-bottom: 2rem;'> <h3 style='font-size:1rem;margin:0 0 0.8rem;padding-bottom:0.5rem;border-bottom:2px solid var(--border);'>ラベル</h3> <div class='tags'>${labelHtml}</div> </div>`} let mobileHashtagsSection="";if(BLOG_CONFIG.showHashtags&&hashtagHtml){mobileHashtagsSection=` <div style='margin-bottom: 2rem;'> <h3 style='font-size:1rem;margin:0 0 0.8rem;padding-bottom:0.5rem;border-bottom:2px solid var(--border);'>ハッシュタグ</h3> <div class='tags'>${hashtagHtml}</div> </div>`} mobileContainer.innerHTML=` <div class='search-widget' style='margin-bottom: 2rem;'> <form action='/search' class='search-form' method='get'> <input class='search-input' name='q' placeholder='検索...' type='text'/> <button class='search-submit' type='submit'>${svgSearch}</button> </form> </div> <div class='mobile-nav-navigation' style='margin-bottom: 2rem;'> <nav class='mobile-nav-nav'> ${mobileNavHtml} </nav> </div> ${mobileLabelsSection} ${mobileHashtagsSection} `;mobileContainer.querySelectorAll('.accordion-trigger').forEach(trigger=>{trigger.addEventListener('click',(e)=>{e.preventDefault();e.stopPropagation();const parent=trigger.closest('.has-dropdown');if(parent){parent.classList.toggle('is-open')}})})}
